import { cacheTag, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

async function ProductList() {
  'use cache';
  cacheTag('products');

  const products = await getAllProducts();

  return (
    <div>
      <h2>Product Listing</h2>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li key={product.id} style={{ padding: '10px', borderBottom: '1px solid #eee' }}>
            <strong>{product.name}</strong> - ${product.price}
          </li>
        ))}
      </ul>
      <p style={{ fontSize: '12px', color: '#666', marginTop: '20px' }}>
        Last fetched: {new Date().toLocaleTimeString()}
      </p>
    </div>
  );
}

export default function Page() {
  async function invalidateProducts() {
    'use server';
    revalidateTag('products', 'profile=max');
  }

  return (
    <div style={{ padding: '20px', maxWidth: '600px', margin: '0 auto' }}>
      <h1>Home</h1>

      <ProductList />

      <form action={invalidateProducts} style={{ marginTop: '20px' }}>
        <button
          type="submit"
          style={{
            padding: '10px 20px',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '5px',
            cursor: 'pointer'
          }}
        >
          Refresh Products
        </button>
        <p style={{ fontSize: '12px', color: '#666', marginTop: '10px' }}>
          Click to invalidate cache and fetch fresh data
        </p>
      </form>
    </div>
  );
}

